// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OrderFeeCorrectionRequest) predicate.OrderFeeCorrectionRequest {
	return predicate.OrderFeeCorrectionRequest(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
